// DEV_RIO_702 X(Twitter)投稿【下書き準備のみ・dry-run】。
// DEV_RIO_201 と同一方針: 公開・自動投稿はしない。人間が内容を確認し、別途手動で公開する。
// CLAUDE.md 絶対禁止事項『本番SNS自動投稿の実行』に準拠。★このワークフローは投稿APIを呼ばない。
// 入力: DEV_RIO_103 の記事下書き（note_body / title / theme 等）。
const i = $input.first().json;
const title = i.title ?? '（タイトル未設定）';
const note_body = i.note_body ?? i.note_draft_body ?? '';
const theme = i.theme ?? 'store-ai';
const experiment_id = i.experiment_id ?? 'exp-001';
return [{ json: {
  content_id: i.content_id ?? 'ca-x-001',
  title, theme, experiment_id,
  source_excerpt: note_body.slice(0, 400),
  platform: 'x',
  action_type: 'prepare_x_drafts'
} }];

