// Claude応答をパースし、下書き候補を整形。冪等性キー付与。公開直前で停止。
const prev = $input.first().json;
let drafts = [];
try {
  const text = prev?.content?.[0]?.text ?? '[]';
  const match = text.match(/\[[\s\S]*\]/);
  drafts = match ? JSON.parse(match[0]) : [];
} catch (e) {
  drafts = [{ angle: 'parse_error', text: 'Claude応答のパースに失敗。手動で下書きを作成してください。', error: String(e) }];
}
const ctx = $('Ingest Content').first().json;
const idempotency_key = [ctx.platform, ctx.content_id, ctx.action_type].join('|');
return [{ json: {
  content_id: ctx.content_id,
  platform: 'x',
  drafts,
  draft_count: drafts.length,
  idempotency_key,
  state: 'WAITING_APPROVAL',
  published: false,
  note: 'dry-run。X投稿の下書き候補のみ生成。★自動投稿はしない。人間が内容を確認し、問題なければ手動でXに投稿する（CLAUDE.md 準拠）。'
} }];
